insert into public.translations (locale, key, value) values
  ('pt-BR', 'app.updates.auto', $json$"O JayV procura uma versão nova ao abrir e a cada 15 segundos. Quando houver uma, um aviso aparece no topo de todas as telas."$json$::jsonb),
  ('pt-BR', 'update.notes.after', $json$"A lista do que mudou abre no seu idioma logo depois da atualização, na janela Novidades. Você pode abri-la de novo quando quiser em Configurações › App › Versão."$json$::jsonb),
  ('pt-BR', 'beat.agent.started', $json$"O agente iniciou a sessão"$json$::jsonb),
  ('pt-BR', 'beat.agent.finished', $json$"O agente terminou"$json$::jsonb),
  ('pt-BR', 'beat.agent.toolResult', $json$"O agente recebeu o resultado de uma ferramenta"$json$::jsonb),
