  ('en', 'explain.last', $json$"The last request used {model} through {provider}. The context had {files} files and an estimated budget of {tokens} tokens."$json$::jsonb),
  ('en', 'explain.none', $json$"There is no previous routing decision in this session."$json$::jsonb),
  ('en', 'whatsNew.item.translationsComplete.title', $json$"Every text in your language"$json$::jsonb),
  ('en', 'whatsNew.item.translationsComplete.detail', $json$"JayV read only the first 1,000 translated texts of each language, so the newest ones, such as the What's new window, the Lean code option in your profile and the version section in Settings, appeared in English. It now reads them all."$json$::jsonb),
  ('en', 'whatsNew.item.updateEvery15s.title', $json$"Updates found within seconds"$json$::jsonb),
  ('en', 'whatsNew.item.updateEvery15s.detail', $json$"JayV now looks for a new version every 15 seconds, with no setting to choose. When one is out, the notice appears at the top of every screen."$json$::jsonb),
  ('en', 'whatsNew.item.translatedSteps.title', $json$"Request steps in your language"$json$::jsonb),
  ('en', 'whatsNew.item.translatedSteps.detail', $json$"The steps shown while a request runs, such as what Jev read, the route and what the agent is doing, are now written in your language instead of the raw event names. The update window now points to What's new instead of showing the release notes, which were in a single language."$json$::jsonb),
  ('es', 'app.updates.auto', $json$"JayV busca una versión nueva al abrirse y cada 15 segundos. Cuando hay una, aparece un aviso en la parte superior de todas las pantallas."$json$::jsonb),
  ('es', 'update.notes.after', $json$"La lista de cambios se abre en tu idioma justo después de actualizar, en la ventana Novedades. Puedes volver a abrirla cuando quieras en Ajustes › App › Versión."$json$::jsonb),
