  ('fr', 'intent.test', $json$"Tests"$json$::jsonb),
  ('fr', 'explain.last', $json$"La dernière demande a utilisé {model} via {provider}. Le contexte comptait {files} fichiers et un budget estimé de {tokens} tokens."$json$::jsonb),
  ('fr', 'explain.none', $json$"Il n’y a encore aucune décision de routage dans cette session."$json$::jsonb),
  ('fr', 'whatsNew.item.translationsComplete.title', $json$"Tous les textes dans votre langue"$json$::jsonb),
  ('fr', 'whatsNew.item.translationsComplete.detail', $json$"JayV ne lisait que les 1 000 premiers textes traduits de chaque langue, si bien que les plus récents, comme la fenêtre Nouveautés, l’option Lean code du profil et la section Version des Paramètres, s’affichaient en anglais. Il les lit désormais tous."$json$::jsonb),
  ('fr', 'whatsNew.item.updateEvery15s.title', $json$"Mises à jour repérées en quelques secondes"$json$::jsonb),
  ('fr', 'whatsNew.item.updateEvery15s.detail', $json$"JayV cherche désormais une nouvelle version toutes les 15 secondes, sans réglage à choisir. Dès qu’une version sort, l’avis apparaît en haut de chaque écran."$json$::jsonb),
  ('fr', 'whatsNew.item.translatedSteps.title', $json$"Étapes de la demande dans votre langue"$json$::jsonb),
  ('fr', 'whatsNew.item.translatedSteps.detail', $json$"Les étapes affichées pendant une demande, comme ce que Jev a lu, la route et ce que fait l’agent, sont désormais écrites dans votre langue au lieu des noms bruts des événements. La fenêtre de mise à jour renvoie maintenant vers Nouveautés au lieu d’afficher les notes de version, qui étaient dans une seule langue."$json$::jsonb),
  ('ru', 'app.updates.auto', $json$"JayV ищет новую версию при запуске и каждые 15 секунд. Когда она выходит, вверху каждого экрана появляется уведомление."$json$::jsonb),
  ('ru', 'update.notes.after', $json$"Список изменений откроется на вашем языке сразу после обновления, в окне «Что нового». Его можно открыть снова в любой момент в разделе Настройки › Приложение › Версия."$json$::jsonb),
  ('ru', 'beat.agent.started', $json$"Агент начал сеанс"$json$::jsonb),
  ('ru', 'beat.agent.finished', $json$"Агент закончил"$json$::jsonb),
  ('ru', 'beat.agent.toolResult', $json$"Агент получил результат инструмента"$json$::jsonb),
