  ('ja', 'intent.test', $json$"テスト"$json$::jsonb),
  ('ja', 'explain.last', $json$"直前のリクエストは {provider} 経由で {model} を使用しました。コンテキストは {files} ファイル、推定予算は {tokens} トークンでした。"$json$::jsonb),
  ('ja', 'explain.none', $json$"このセッションにはまだルーティングの判断がありません。"$json$::jsonb),
  ('ja', 'whatsNew.item.translationsComplete.title', $json$"すべてのテキストをあなたの言語で"$json$::jsonb),
  ('ja', 'whatsNew.item.translationsComplete.detail', $json$"JayV は各言語の翻訳を最初の 1,000 件しか読んでいなかったため、「新機能」ウィンドウ、プロフィールの Lean code オプション、設定のバージョン欄など新しいテキストが英語で表示されていました。現在はすべて読み込みます。"$json$::jsonb),
  ('ja', 'whatsNew.item.updateEvery15s.title', $json$"数秒で更新を検出"$json$::jsonb),
  ('ja', 'whatsNew.item.updateEvery15s.detail', $json$"JayV は設定なしで 15 秒ごとに新しいバージョンを確認するようになりました。公開されると、すべての画面の上部にお知らせが表示されます。"$json$::jsonb),
  ('ja', 'whatsNew.item.translatedSteps.title', $json$"リクエストの手順をあなたの言語で"$json$::jsonb),
  ('ja', 'whatsNew.item.translatedSteps.detail', $json$"リクエスト実行中に表示される手順（Jev の読み取り結果、ルート、エージェントの作業内容など）が、生のイベント名ではなくあなたの言語で表示されるようになりました。更新ウィンドウは、1 つの言語のみだったリリースノートの代わりに「新機能」を案内します。"$json$::jsonb),
  ('de', 'app.updates.auto', $json$"JayV sucht beim Öffnen und alle 15 Sekunden nach einer neuen Version. Gibt es eine, erscheint oben auf jedem Bildschirm ein Hinweis."$json$::jsonb),
  ('de', 'update.notes.after', $json$"Die Liste der Änderungen öffnet sich direkt nach dem Update in Ihrer Sprache im Fenster Neuigkeiten. Sie können sie jederzeit unter Einstellungen › App › Version erneut öffnen."$json$::jsonb),
  ('de', 'beat.agent.started', $json$"Der Agent hat seine Sitzung gestartet"$json$::jsonb),
  ('de', 'beat.agent.finished', $json$"Der Agent ist fertig"$json$::jsonb),
  ('de', 'beat.agent.toolResult', $json$"Der Agent hat ein Werkzeugergebnis erhalten"$json$::jsonb),
