  ('de', 'intent.security', $json$"Sicherheit"$json$::jsonb),
  ('de', 'intent.test', $json$"Tests"$json$::jsonb),
  ('de', 'explain.last', $json$"Die letzte Anfrage hat {model} über {provider} verwendet. Der Kontext hatte {files} Dateien und ein geschätztes Budget von {tokens} Tokens."$json$::jsonb),
  ('de', 'explain.none', $json$"In dieser Sitzung gibt es noch keine Routing-Entscheidung."$json$::jsonb),
  ('de', 'whatsNew.item.translationsComplete.title', $json$"Alle Texte in Ihrer Sprache"$json$::jsonb),
  ('de', 'whatsNew.item.translationsComplete.detail', $json$"JayV hat pro Sprache nur die ersten 1.000 übersetzten Texte gelesen, daher erschienen die neuesten, etwa das Fenster Neuigkeiten, die Option Lean code im Profil und der Versionsbereich in den Einstellungen, auf Englisch. Jetzt liest es alle."$json$::jsonb),
  ('de', 'whatsNew.item.updateEvery15s.title', $json$"Updates in Sekunden gefunden"$json$::jsonb),
  ('de', 'whatsNew.item.updateEvery15s.detail', $json$"JayV sucht jetzt alle 15 Sekunden nach einer neuen Version, ohne Einstellung. Sobald eine erscheint, steht der Hinweis oben auf jedem Bildschirm."$json$::jsonb),
  ('de', 'whatsNew.item.translatedSteps.title', $json$"Anfrageschritte in Ihrer Sprache"$json$::jsonb),
  ('de', 'whatsNew.item.translatedSteps.detail', $json$"Die Schritte, die während einer Anfrage angezeigt werden, etwa was Jev gelesen hat, die Route und was der Agent tut, stehen jetzt in Ihrer Sprache statt als rohe Ereignisnamen. Das Update-Fenster verweist jetzt auf Neuigkeiten, statt die Versionshinweise in nur einer Sprache zu zeigen."$json$::jsonb)
